<?php /** @var \Sysfera\Plugin $sf @var string $tab @var array $kp */
include __DIR__ . '/_nav.php'; $t = $kp['total']; $fmt = fn($v, string $u = '') => $v === null ? '—' : e((string)$v) . $u; ?>
<div class="page-h"><h1><?= e($sf->t('nav_kpi')) ?></h1><span class="row"><?php foreach ([7, 30, 90, 365] as $d): ?><a class="btn sm <?= $kp['days'] === $d ? 'primary' : '' ?>" href="<?= e($sf->url('/kpi?days=' . $d)) ?>"><?= $d ?> <?= e($sf->t('kpi_days')) ?></a><?php endforeach; ?></span></div>
<p class="muted"><?= e($kp['from']) ?> — <?= e($kp['to']) ?></p>
<div class="gi-tiles"><div class="card gi-tile"><b><?= (int)$t['issued'] ?></b><span><?= e($sf->t('kpi_issued')) ?></span></div><div class="card gi-tile"><b><?= (int)$t['waiting'] ?></b><span><?= e($sf->t('kpi_waiting')) ?></span></div>
  <div class="card gi-tile"><b><?= $fmt($t['discrepancy_rate'], '%') ?></b><span><?= e($sf->t('kpi_disc_rate')) ?></span></div><div class="card gi-tile"><b><?= (int)$t['suspicious'] ?></b><span><?= e($sf->t('kpi_suspicious')) ?></span></div></div>
<div class="card flush"><table class="tbl"><thead><tr><th><?= e($sf->t('warehouse')) ?></th><th><?= e($sf->t('kpi_issued')) ?></th><th><?= e($sf->t('kpi_speed')) ?></th><th><?= e($sf->t('kpi_storage')) ?></th><th><?= e($sf->t('kpi_waiting')) ?></th><th><?= e($sf->t('kpi_oldest')) ?></th><th><?= e($sf->t('kpi_disc_rate')) ?></th><th><?= e($sf->t('kpi_returns')) ?></th><th><?= e($sf->t('kpi_courier')) ?></th><th><?= e($sf->t('kpi_suspicious')) ?></th></tr></thead><tbody>
<?php foreach ($kp['warehouses'] as $w): ?><tr><td><b><?= e($w['name']) ?></b></td><td><?= (int)$w['issued'] ?></td><td><?= $fmt($w['issue_hours_avg'], ' h') ?><br><small class="muted"><?= e($sf->t('kpi_median')) ?> <?= $fmt($w['issue_hours_median'], ' h') ?></small></td><td><?= $fmt($w['storage_days_avg'], ' d') ?></td><td><?= (int)$w['waiting'] ?><br><small class="muted"><?= $fmt($w['waiting_days_avg'], ' d') ?></small></td><td><?= $fmt($w['oldest_waiting_days'], ' d') ?></td>
  <td><?= $fmt($w['discrepancy_rate'], '%') ?><br><small class="muted"><?= (int)$w['discrepancy_orders'] ?> / <?= (int)$w['received'] ?></small></td><td><?= (int)$w['returns'] ?></td><td><?= (int)$w['courier'] ?></td><td><?= (int)$w['suspicious'] ?></td></tr><?php endforeach; ?>
<?php if (!$kp['warehouses']): ?><tr><td colspan="10" class="muted"><?= e($sf->t('none')) ?></td></tr><?php endif; ?></tbody></table></div>
<h3><?= e($sf->t('kpi_operators')) ?></h3>
<div class="card flush"><table class="tbl"><thead><tr><th><?= e($sf->t('kpi_operator')) ?></th><th><?= e($sf->t('warehouse')) ?></th><th><?= e($sf->t('kpi_actions')) ?></th><th><?= e($sf->t('kpi_a_issues')) ?></th><th><?= e($sf->t('kpi_a_receipts')) ?></th><th><?= e($sf->t('kpi_a_returns')) ?></th><th><?= e($sf->t('kpi_a_counts')) ?></th><th><?= e($sf->t('kpi_a_failed')) ?></th><th><?= e($sf->t('kpi_last')) ?></th></tr></thead><tbody>
<?php foreach ($kp['operators'] as $o): ?><tr><td><b><?= e($o['actor']) ?></b></td><td><?= e(implode(', ', $o['warehouses'])) ?></td><td><?= (int)$o['actions'] ?></td><td><?= (int)$o['issues'] ?></td><td><?= (int)$o['receipts'] ?></td><td><?= (int)$o['returns'] ?></td><td><?= (int)$o['counts'] ?></td><td><?= (int)$o['failed_codes'] ?></td><td class="muted"><?= e($o['last']) ?></td></tr><?php endforeach; ?>
<?php if (!$kp['operators']): ?><tr><td colspan="9" class="muted"><?= e($sf->t('none')) ?></td></tr><?php endif; ?></tbody></table></div>
<h3><?= e($sf->t('kpi_suspicious')) ?></h3>
<?php if (!$kp['suspicious']): ?><div class="card empty"><p class="muted"><?= e($sf->t('kpi_nothing')) ?></p></div><?php endif; ?>
<?php foreach ($kp['suspicious'] as $s): ?><div class="card"><p><span class="gi-sev gi-sev-<?= in_array($s['type'], ['manual_override', 'clock_ahead'], true) ? 'medium' : 'high' ?>"><?= e($sf->t('sus_' . $s['type'])) ?></span>
  <b><?= $s['order'] !== '' ? '<a href="' . e($sf->url('/orders/' . $s['order'])) . '">#' . e($s['ref']) . '</a>' : e($s['ref']) ?></b> × <?= (int)$s['count'] ?> · <span class="muted"><?= e($s['who']) ?> <?= $s['device'] !== '' ? '· ' . e(substr($s['device'], 0, 10)) : '' ?> · <?= e(date('Y-m-d H:i', (int)$s['ts'])) ?></span></p></div><?php endforeach; ?>
